"use client";

/** Renders the Fish Tap screen and connects browser input and animation frames to the game engine. */
import Image from "next/image";
import { useEffect, useReducer, useRef } from "react";
import { fishTapAssets } from "./asset-catalog";
import {
  initialFishTapState,
  reduceFishTapGame,
} from "./game-engine";
import styles from "./fish-tap-game.module.css";

/**
 * What it does: Displays the playable Fish Tap game and dispatches user and animation events.
 * Can be generated by AI?: Yes.
 */
export function FishTapGame() {
  const arenaRef = useRef<HTMLDivElement>(null);
  const [state, dispatch] = useReducer(
    reduceFishTapGame,
    initialFishTapState,
  );

  useEffect(() => {
    if (state.phase !== "playing") return;

    let frameId = 0;

    const tick = (now: number) => {
      const arenaWidth = arenaRef.current?.clientWidth ?? 720;

      dispatch({
        type: "FRAME",
        now,
        arenaWidth,
      });

      frameId = requestAnimationFrame(tick);
    };

    frameId = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frameId);
  }, [state.phase]);

  const startGame = () => {
    dispatch({ type: "START", now: performance.now() });
  };

  const replayGame = () => {
    dispatch({ type: "REPLAY" });
    requestAnimationFrame(() => {
      dispatch({ type: "START", now: performance.now() });
    });
  };

  const timeLeft = Math.ceil(state.timeLeftMs / 1000);
  const totalAttempts = state.caught + state.missed;
  const accuracy = totalAttempts
    ? Math.round((state.caught / totalAttempts) * 100)
    : 0;

  return (
    <section className={styles.game} aria-label="Fish Tap game">
      <div className={styles.hud}>
        <Stat label="Time left" value={`${timeLeft}s`} />
        <Stat label="Score" value={state.score} />
        <Stat label="Missed" value={state.missed} />
      </div>

      <div ref={arenaRef} className={styles.arena}>
        <div className={styles.ground} aria-hidden="true" />

        {state.fish.map((fish) => (
          <button
            key={fish.id}
            type="button"
            className={styles.fish}
            style={{ transform: `translate(${fish.x}px, ${fish.y}px)` }}
            onPointerDown={() =>
              dispatch({
                type: "TAP_FISH",
                fishId: fish.id,
                now: performance.now(),
              })
            }
            aria-label="Catch fish"
          >
            <Image
              src={fishTapAssets.fish.src}
              alt=""
              width={64}
              height={64}
              draggable={false}
            />
          </button>
        ))}

        {state.phase !== "playing" && (
          <div className={styles.overlay}>
            {state.phase === "intro" ? (
              <>
                <h1>Fish Tap</h1>
                <p>
                  Tap each fish before it reaches the ground. You have 30
                  seconds.
                </p>
                <button type="button" onClick={startGame}>
                  Start game
                </button>
              </>
            ) : (
              <>
                <h1>Time is up</h1>
                <p className={styles.finalScore}>Final score: {state.score}</p>
                <div className={styles.results}>
                  <Stat label="Caught" value={state.caught} />
                  <Stat label="Missed" value={state.missed} />
                  <Stat label="Accuracy" value={`${accuracy}%`} />
                </div>
                <button type="button" onClick={replayGame}>
                  Play again
                </button>
              </>
            )}
          </div>
        )}
      </div>
    </section>
  );
}

/**
 * What it does: Displays one labelled game statistic, such as score or time remaining.
 * Can be generated by AI?: Yes.
 */
function Stat({ label, value }: { label: string; value: string | number }) {
  return (
    <div className={styles.stat}>
      <span>{label}</span>
      <strong>{value}</strong>
    </div>
  );
}
